(()=>{const prior=homeHTML;homeHTML=function(){const box=document.createElement('div');box.innerHTML=prior();const h=box.querySelector('.hero-copy h1');if(h)h.textContent='بطاقات ولاء تعيد عملاءك.';const footer=box.querySelector('.info-footer');if(footer)footer.insertAdjacentHTML('beforebegin',`<section class="seo-services" aria-labelledby="loyalty-services"><span>برنامج ولاء يناسب نشاطك</span><h2 id="loyalty-services">من أول زيارة إلى مكافأة يستحقها العميل</h2><p>رِجعة منصة بطاقات ولاء رقمية بالزيارات والنقاط والخصومات، مع Apple Wallet وGoogle Wallet، وإدارة الفروع والموظفين وتقارير المبالغ المسجلة.</p><div><a href="/loyalty-cards.html"><strong>بطاقات الولاء الرقمية</strong><small>كيف تختار برنامجك وتبدأ؟ ↗</small></a><a href="/coffee-loyalty.html"><strong>ولاء الكافيهات</strong><small>زيارات ومكافآت القهوة ↗</small></a><a href="/car-wash-loyalty.html"><strong>ولاء مغاسل السيارات</strong><small>برامج غسيل وفروع متعددة ↗</small></a><a href="/salon-loyalty.html"><strong>ولاء الحلاقين والصالونات</strong><small>نقاط ومكافآت على الخدمات ↗</small></a></div></section>`);return box.innerHTML;};if(publicPage==='home')render();})();
